#!/usr/bin/env bash
# Run 3, batch 7: the scaffolded list ViewModel's two "rows written after ..." tests seen red. In the audit project
# (generated by v6.sh), the observer's reducer loses its Empty and Error branches; :feature:order's tests must then
# fail on exactly those two cases, and pass again once the file is restored.
#   bash v7.sh > logs/v7.log 2>&1
set -uo pipefail
export LOCKED_PRIORITY=low
OV=D:/projects/tools/.overhaul
O=$OV/out/WP02-CONT
L=$OV/bin/locked
GW="bash $OV/out/WP02/gw.win.sh"
P=$O/audit
VM=$P/feature/order/src/main/kotlin/io/example/audit/feature/order/list/OrderListViewModel.kt
R=$P/feature/order/build/test-results/testDebugUnitTest
step() { echo; echo "== $(date +%H:%M:%S) $*"; }
summary() {
  python - $R <<'PY'
import sys, glob, xml.etree.ElementTree as ET
for f in glob.glob(sys.argv[1] + "/TEST-*ListViewModelTest.xml"):
    for case in ET.parse(f).getroot().iter("testcase"):
        bad = case.find("failure") is not None or case.find("error") is not None
        print(("FAIL " if bad else "pass ") + case.get("name"))
PY
}

cp $VM $O/logs/v7-OrderListViewModel.kt.orig
python -I - $VM <<'PY'
import sys
path = sys.argv[1]
text = open(path, encoding="utf-8").read()
line = "    rows && (this == LoadState.Empty || this is LoadState.Error) -> LoadState.Success\n"
assert text.count(line) == 1, "the reducer line is not in the generated file"
open(path, "w", encoding="utf-8", newline="\n").write(text.replace(line, ""))
PY
step "mutated: the reducer without its Empty and Error branches (expect the two cases FAIL)"
(cd $P && $L gradle $GW --offline :feature:order:testDebugUnitTest --console=plain) > $O/logs/v7-mutated.log 2>&1; echo "rc=$?"
summary
cp $O/logs/v7-OrderListViewModel.kt.orig $VM

step "restored (expect every case pass)"
(cd $P && $L gradle $GW --offline :feature:order:testDebugUnitTest --console=plain) > $O/logs/v7-restored.log 2>&1; echo "rc=$?"
summary

echo; echo "V7 DONE $(date +%H:%M:%S)"
